<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Composition with Red, Blue and Yellow — Piet Mondrian, 1930</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Archivo:wght@400;500;700;900&display=swap" rel="stylesheet">
<style>
  :root {
    --red: #d40000;
    --blue: #0033a0;
    --yellow: #f5c400;
    --black: #111111;
    --white: #f7f5f0;
    --grey: #8a8a8a;
    --bar: 14px;
  }
  * { margin: 0; padding: 0; box-sizing: border-box; }
  html { scroll-behavior: smooth; }
  body {
    font-family: 'Archivo', 'Helvetica Neue', Arial, sans-serif;
    background: var(--white);
    color: var(--black);
    line-height: 1.5;
  }

  /* ---------- Mondrian grid layout ---------- */
  .grid {
    display: grid;
    grid-template-columns: repeat(12, 1fr);
    grid-template-rows: auto;
    gap: var(--bar);
    background: var(--black);
    min-height: 100vh;
    padding: var(--bar);
  }
  .cell {
    background: var(--white);
    padding: clamp(20px, 4vw, 48px);
    display: flex;
    flex-direction: column;
    justify-content: center;
  }
  .cell.red    { background: var(--red);    color: var(--white); }
  .cell.blue   { background: var(--blue);   color: var(--white); }
  .cell.yellow { background: var(--yellow); color: var(--black); }
  .cell.grey   { background: #e4e1da; }

  /* ---------- Hero: the painting ---------- */
  .hero {
    grid-column: 1 / 9;
    grid-row: 1;
    padding: 0;
    background: var(--white);
  }
  .painting {
    width: 100%;
    height: auto;
    display: block;
  }
  .hero-caption {
    grid-column: 9 / 13;
    grid-row: 1;
    justify-content: flex-start;
    padding-top: clamp(24px, 5vw, 64px);
  }
  .kicker {
    font-size: 13px;
    font-weight: 700;
    letter-spacing: 0.18em;
    text-transform: uppercase;
    margin-bottom: 16px;
  }
  .cell.red .kicker { color: rgba(255,255,255,0.75); }
  h1 {
    font-size: clamp(28px, 3.4vw, 44px);
    font-weight: 900;
    line-height: 1.08;
    letter-spacing: -0.01em;
  }
  .meta {
    margin-top: 18px;
    font-size: 15px;
    font-weight: 500;
  }
  .meta strong { font-weight: 700; }

  /* ---------- Sections ---------- */
  .painter  { grid-column: 1 / 5;  grid-row: 2; }
  .movement { grid-column: 5 / 13; grid-row: 2; }
  .why      { grid-column: 1 / 9;  grid-row: 3; }
  .source   { grid-column: 9 / 13; grid-row: 3; }

  h2 {
    font-size: 13px;
    font-weight: 700;
    letter-spacing: 0.18em;
    text-transform: uppercase;
    margin-bottom: 14px;
  }
  .cell.red h2, .cell.blue h2 { color: rgba(255,255,255,0.75); }
  .body { font-size: 16px; max-width: 52ch; }
  .body + .body { margin-top: 12px; }

  /* ---------- Principle swatches ---------- */
  .swatches {
    display: flex;
    gap: 10px;
    margin-top: 18px;
    flex-wrap: wrap;
  }
  .swatch {
    width: 44px;
    height: 44px;
    border: 3px solid var(--black);
  }
  .swatch.red    { background: var(--red); }
  .swatch.blue   { background: var(--blue); }
  .swatch.yellow { background: var(--yellow); }
  .swatch.white  { background: var(--white); }
  .swatch.grey   { background: var(--grey); }
  .swatch.black  { background: var(--black); }
  .swatch-label {
    width: 100%;
    font-size: 12px;
    font-weight: 500;
    color: var(--grey);
    margin-top: 2px;
  }

  /* ---------- CTA ---------- */
  .source { justify-content: center; align-items: flex-start; }
  .cta {
    display: inline-block;
    background: var(--black);
    color: var(--white);
    text-decoration: none;
    font-weight: 700;
    font-size: 15px;
    padding: 16px 22px;
    margin-top: 18px;
    border: 3px solid var(--black);
    transition: background 0.15s, color 0.15s;
  }
  .cta:hover { background: var(--white); color: var(--black); }
